mapper.select:
select m.area_name ,c.item_cd ,i.item_name ,a.make_no ,a.lot_no ,a.lot_no2 ,co.code_nm as batch_status ,b.prod_qty ,b.coating_qty ,b.charging_qty ,b.packing_qty from TB_WORK_ORDER_BATCH a left join ( select work_batch_id , max(case when proc_cd = 'PRC002' then prod_qty end) as prod_qty-- 제조 , max(case when proc_cd = 'PRC003' then prod_qty end) as coating_qty-- 코팅 , max(case when proc_cd = 'PRC004' then prod_qty end) as charging_qty-- 충전 , max(case when proc_cd = 'PRC005' then prod_qty end) as packing_qty-- 포장 from TB_WORK_ORDER_PROC group by work_batch_id ) b on A.work_batch_id = B.work_batch_id left join TB_WORK_ORDER_MST c on c.work_order_id = a.work_order_id left join tb_item_mst i on i.item_cd = c.item_cd left join tb_area_mst m on m.area_cd = c.area_cd left join tb_common_code co on co.code = a.batch_status and co.com_type_cd = 'batch_STATUS' where a.batch_status >= '22' and c.work_order_date between #{strDate} and #{endDate}
and c.area_cd = #{areaCd}
and c.item_cd like '%' + #{itemCd} + '%'
and i.item_name like '%' + #{itemName} + '%'

SELECT  TAG_VALUE_ID
       ,TAG_CD
       ,MEASURE_VALUE
       ,STRING_VALUE
       ,MEASURE_TIME
       ,REG_TIME
FROM tb_tag_value
WHERE  (measure_time  >=  #{strDate}
       AND measure_time  <  #{endDate}
       AND tag_cd = #{tagCd}
    )
ORDER BY measure_time ASC
